pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialDeposits, bool sendEthBefore) public {
        initialDeposits = bound(initialDeposits, 0, 100);
        // Fund the contract by sending ether directly to fallback to create real deposits
        for (uint i = 0; i < initialDeposits; i++) {
            vm.deal(address(this), 1 ether);
            (bool sent,) = address(c).call{value: 1 wei}("");
            require(sent, "send eth failed");
        }
        uint256 depositsBefore = c.depositsCount();

        // Optionally send one more ether before withdrawAll to ensure the count is accurate
        if (sendEthBefore) {
            vm.deal(address(this), 1 ether);
            (bool sent,) = address(c).call{value: 1 wei}("");
            require(sent, "send eth before failed");
        }

        // Owner calls withdrawAll
        vm.prank(c.owner());
        c.withdrawAll();

        // After withdrawAll, the deposit count must equal the number of ether receipts.
        // Since withdrawAll does not send ether to the contract, the mutant's increment is wrong.
        assertEq(c.depositsCount(), depositsBefore);
    }
}

