pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositsBefore, bool callWithdrawAll) public {
        // 1. Bound the number of preliminary deposits to avoid arithmetic overflow (keep domain wide)
        depositsBefore = bound(depositsBefore, 0, 1000);
        // 2. Simulate receiving ether into the contract via fallback (which increments depositsCount)
        for (uint i = 0; i < depositsBefore; i++) {
            vm.deal(address(this), 1 ether);
            (bool s, ) = address(c).call{value: 1 ether}("");
            require(s, "fallback call failed");
        }
        uint256 expectedDeposits = c.depositsCount();
        // 3. Possibly call withdrawAll (always as owner, as this function enforces onlyOwner)
        if (callWithdrawAll) {
            vm.prank(c.owner());
            c.withdrawAll();
        }
        // 4. After the sequence, depositsCount must equal the number of ether receipts (expectedDeposits).
        //    Calling withdrawAll without receiving ether should not change depositsCount.
        assertTrue(c.depositsCount() == expectedDeposits);
    }
}

