pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, bool withdrawAllFirst) public {
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount <= depositAmount);
        // Setup: fund depositor and make a deposit via fallback to set initial state
        address depositor = makeAddr("depositor");
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        (bool ok,) = address(c).call{value: depositAmount}("");
        require(ok, "deposit failed");

        // Withdraw part of the balance (or all) as the owner
        address owner = c.owner();
        if (withdrawAllFirst) {
            vm.prank(owner);
            c.withdrawAll();
        } else {
            vm.prank(owner);
            c.withdraw(withdrawAmount);
        }

        // Invariant: depositsCount must equal the contract's ether balance
        assertTrue(c.depositsCount() == address(c).balance);
    }
}

