// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint8 helperSeed) public {
        // Restrict amount to a reasonable range bounded by current contract balance
        vm.deal(address(c), 100 ether);
        amount = bound(amount, 1, address(c).balance);

        // Deploy an adversarial helper that cannot accept Ether
        CantAcceptEther helper = new CantAcceptEther();

        // Transfer ownership to the helper — this makes it the only allowed caller
        // The helper will then call withdraw, and its inability to receive Ether
        // is exactly the adversarial behavior needed to trigger the bug.
        vm.prank(address(c.owner()));
        c.sendMoney(address(helper), 0, abi.encodeWithSignature("transferOwnershipAndWithdraw(uint256)", amount));
    }
}

// Minimal adversarial helper that first calls a function on C to transfer ownership,
// then calls withdraw. It has no payable fallback, so any transfer/call with value to it fails.
contract CantAcceptEther {
    function transferOwnershipAndWithdraw(uint256 amount) external {
        C c = C(msg.sender);
        // This helper is now the owner, so it can call withdraw
        // We use a low-level call to C's withdraw, which will attempt to send Ether back to this contract.
        // Because this contract has no payable fallback, the transfer/call fails.
        // In the reference (using transfer), the transaction reverts.
        // In the mutant (using call without check), the transaction succeeds but no Ether is actually sent.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", amount));
        require(ok, "withdraw call failed");
    }
}

