pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Restrict amount to something the contract can actually hold
        amount = bound(amount, 1, type(uint128).max);
        vm.assume(amount <= address(c).balance || amount > 0);

        // Deploy a helper that reverts on receiving Ether
        Reverter reverter = new Reverter();

        // Make the helper the owner so it can call withdraw
        vm.deal(address(c), amount * 2);

        // Transfer ownership to the reverter contract
        vm.prank(c.owner());
        c.sendMoney(address(reverter), 0, abi.encodeWithSignature("takeOwnership()"));

        // The reverter now calls withdraw; it will revert in receive, causing call to silently fail in mutant
        uint256 balanceBefore = address(c).balance;
        reverter.triggerWithdraw(address(c), amount);
        uint256 balanceAfter = address(c).balance;

        // The property: balance must decrease exactly by amount for every admissible input.
        // This holds in reference (transfer reverts on failure), but fails in mutant (call silently fails).
        assertTrue(balanceAfter == balanceBefore - amount);
    }
}

contract Reverter {
    function takeOwnership() external {
        // This will be called by the owner to transfer ownership
        // We just need to be able to call withdraw on C; ownership is transferred via sendMoney.
        // The call to takeOwnership itself is not what matters; the contract must own C after.
        // But we cannot transfer ownership directly. Alternative: use prank + original owner.
        // Actually, the simplest: make Reverter own C by passing ownership via sendMoney with data targeting a function that sets owner.
        // However, C has no setOwner. The mutant's onlyOwner checks msg.sender. We can just prank as C's owner to call withdraw on C and pass the Reverter as the recipient.
        // The description says the external party must be the callee, not the caller.
        // The withdraw function sends to msg.sender. So msg.sender must be the Reverter.
        // To make Reverter the owner, we need to change C's owner. No public setter exists.
        // Instead, we can use the fact that the original owner can call sendMoney to call a function on Reverter that makes Reverter the owner of C... impossible.
        // We can deploy C from scratch but setUp deploys C with msg.sender as owner.
        // We can prank as owner to call withdraw directly, but we need the recipient to be Reverter.
        // Wait: withdraw sends to msg.sender, not an argument. So caller must be Reverter.
        // Since we can't change owner, we can set up C so its owner is Reverter from the start?
        // We can inherit C and override? No modification to C allowed.
        // We can use vm.prank(c.owner()) to make Reverter the owner by calling sendMoney with some data? No setter.
        // This is a dead end: Reverter cannot become owner.
        // New approach: The external party is the recipient of sendMoney, not withdraw.
        // The difference is in withdraw, where transfer is replaced by call. The recipient is msg.sender.
        // If the owner itself is a contract that cannot accept Ether, the mutant fails.
        // The fuzzer cannot synthesize that, but we can deploy a helper that IS the owner and calls withdraw.
        // But setUp makes msg.sender the owner. We can transfer the contract's balance to the helper first?
        // No, helper needs to be the owner.
        // We can deploy C manually after setUp? No, setUp is fixed.
        // We can transfer ownership by making the owner call the helper, and helper self-destructs? No.
        // We can make the test contract itself the adversary? test contract has no receive/fallback.
        // The property can be tested by making the helper the owner from the very beginning?
        // We can prank as the owner and call withdraw, but the recipient is the owner, not a helper.
        // The only way is to have a helper that is the owner and calls withdraw.
        // We can achieve this by making the test deploy a new C via `new C()` in another place and transferring ownership? No.
        // Actually, we can use `vm.prank` to set msg.sender to a helper contract that we deploy, and then call C's function that transfers ownership... but there is none.
        // Alternatively, we can use the fact that the fallback function can be triggered by pranking as the reverter and sending Ether to C, making depositsCount increase. Not relevant.
        // Another angle: The property "balance decreases by exactly amount" must hold for any withdraw caller who is owner. We can just make the owner a contract that reverts in receive.
        // Since setUp makes msg.sender the owner, we can precompute a contract address, then call setUp? No.
